import json
from missing_content import bundle

def add_extra(chapters, add):
    add('module', 'Loguri: acțiuni ale utilizatorilor', 'Citește n și apoi n linii de log. O acțiune umană are forma Nume (email) [YYYY-MM-DD HH:MM]: mesaj; liniile Automation Task [..] sunt automate. Afișează numărul acțiunilor umane, apoi numele în ordine alfabetică și momentele lui în ordinea intrării, separate prin ; .', 'Un regex cu grupuri numite extrage numele și coordonata temporală numai pentru liniile cu email între paranteze.', 'import re\nn = int(input())\nd = {}\nfor _ in range(n):\n    m = re.fullmatch(r"(.+) \\(([^()]+)\\) \\[([^\\]]+)\\]: .+", input())\n    if m:\n        d.setdefault(m.group(1), []).append(m.group(3))\nprint(sum(map(len, d.values())))\nfor name in sorted(d):\n    print(name + ": " + "; ".join(d[name]))', [('3\nAna (a@x.ro) [2026-01-01 10:00]: start\nAutomation Task [2026-01-01 11:00]: backup\nAna (a@x.ro) [2026-01-02 12:00]: stop','2\nAna: 2026-01-01 10:00; 2026-01-02 12:00'),('1\nAutomation Task [2026-01-01 10:00]: backup','0'),('0','0')], 'Aplicare')
    add('module', 'Raport de evenimente', 'Prima linie este data de referință YYYY-MM-DD. Urmează n și n linii nume, YYYY-MM-DD HH:MM. Afișează nume | DD/MM/YYYY HH:MM | diferența între date în zile sau TRECUT dacă data evenimentului precede data de referință.', 'Data de referință este intrare, ca rezultatul testelor să nu depindă de ziua rulării.', 'from datetime import datetime\nref = datetime.strptime(input(), "%Y-%m-%d").date()\nn = int(input())\nfor _ in range(n):\n    name, text = input().split(", ")\n    d = datetime.strptime(text, "%Y-%m-%d %H:%M")\n    days = (d.date() - ref).days\n    state = str(days) if days >= 0 else "TRECUT"\n    print(name + " | " + d.strftime("%d/%m/%Y %H:%M") + " | " + state)', [('2026-01-01\n2\nConcert, 2026-01-03 18:00\nTest, 2025-12-31 10:00','Concert | 03/01/2026 18:00 | 2\nTest | 31/12/2025 10:00 | TRECUT'),('2024-02-28\n1\nE, 2024-03-01 00:00','E | 01/03/2024 00:00 | 2'),('2026-01-01\n0','')], 'Aplicare')
    add('module', 'Rezervări și suprapuneri', 'Citește momentul de referință YYYY-MM-DD HH:MM, n și n linii nume, YYYY-MM-DD HH:MM, durata_minute. Afișează fiecare rezervare ca nume | final YYYY-MM-DD HH:MM | VIITOR/ACTIV/TRECUT | numele celorlalte rezervări suprapuse în ordine alfabetică (sau -). Intervalele sunt [start,final).', 'Două intervale se suprapun dacă max(start1,start2)<min(final1,final2); compară momente complete, inclusiv data.', 'from datetime import datetime, timedelta\nref = datetime.strptime(input(), "%Y-%m-%d %H:%M")\nn = int(input())\na = []\nfor _ in range(n):\n    name, text, duration = input().split(", ")\n    start = datetime.strptime(text, "%Y-%m-%d %H:%M")\n    a.append((name, start, start + timedelta(minutes=int(duration))))\nfor i, (name, start, end) in enumerate(a):\n    others = sorted(x[0] for j, x in enumerate(a) if i != j and max(start, x[1]) < min(end, x[2]))\n    state = "VIITOR" if ref < start else "TRECUT" if ref >= end else "ACTIV"\n    print(name + " | " + end.strftime("%Y-%m-%d %H:%M") + " | " + state + " | " + (" ".join(others) or "-"))', [('2026-01-01 10:30\n2\nAna, 2026-01-01 10:00, 60\nDan, 2026-01-01 10:45, 30','Ana | 2026-01-01 11:00 | ACTIV | Dan\nDan | 2026-01-01 11:15 | VIITOR | Ana'),('2026-01-01 11:00\n1\nA, 2026-01-01 10:00, 60','A | 2026-01-01 11:00 | TRECUT | -'),('2026-01-01 00:00\n0','')], 'Aprofundare')
    add('module', 'Regex: compile, search și grupuri', 'Citește un text. Compilează modelul ([A-Z]+)-([0-9]+), caută prima potrivire și afișează grupul 1, grupul 2, start și end (capăt exclus). Dacă nu există, NU.', 'search poate găsi în interiorul textului; match cere începutul, fullmatch întregul text.', 'import re\np = re.compile(r"([A-Z]+)-([0-9]+)")\nm = p.search(input())\nprint(m.group(1), m.group(2), m.start(), m.end()) if m else print("NU")', [('xx AB-123 zz','AB 123 3 9'),('a-12','NU'),('Z-7','Z 7 0 3')])
    add('module', 'Regex: înlocuire condiționată', 'Citește un text ASCII. Înlocuiește numai numerele urmate de unul sau mai multe spații și cuvântul lei cu [SUMA], păstrând spațiile și lei. Afișează textul și suma numerelor înlocuite pe linii separate.', 'Folosește lookahead pentru context și sub pentru înlocuire; findall calculează suma.', 'import re\ns = input()\np = r"\\b[0-9]+(?=\\s+lei\\b)"\nprint(re.sub(p, "[SUMA]", s))\nprint(sum(map(int, re.findall(p, s))))', [('5 lei si 10 lei, 3 euro','[SUMA] lei si [SUMA] lei, 3 euro\n15'),('123','123\n0'),('0 lei','[SUMA] lei\n0')], 'Aplicare')
    add('module', 'Validare IPv4', 'Citește un text. Afișează DA dacă are exact patru grupuri de cifre ASCII, separate prin punct, fiecare între 0 și 255, fără zerouri inițiale în grupurile de mai multe cifre. Altfel NU.', 'Regex verifică forma; conversia și regulile de interval verifică valorile.', 'import re\ns = input()\na = s.split(".")\nok = len(a) == 4 and all(re.fullmatch(r"[0-9]{1,3}", x) and (x == "0" or not x.startswith("0")) and int(x) <= 255 for x in a)\nprint("DA" if ok else "NU")', [('127.0.0.1','DA'),('256.1.1.1','NU'),('01.2.3.4','NU')], 'Aplicare')
    add('module', 'Atribute HTML', 'Citește un tag HTML simplificat pe o singură linie; numele atributelor sunt litere/underscore, valorile sunt în ghilimele duble. Afișează numele atributelor găsite crescător. Nu se cere un parser HTML general.', 'Un regex cu grup capturant găsește numele înainte de = și valoarea între ghilimele.', 'import re\ns = input()\nq = chr(34)\na = re.findall(r"([A-Za-z_]+)\\s*=\\s*" + q + "[^" + q + "]*" + q, s)\nprint(*sorted(set(a)))', [('<a href="https://x.ro" title="X">','href title'),('<p>',''),('<img alt="a" src="b">','alt src')], 'Aplicare')
    add('bucle', 'Intervalul comun tuturor', 'Citește n ≥ 1 și n intervale închise cu capete întregi. Afișează intersecția lor ca stânga dreapta sau NU dacă este vidă.', 'Maximul capetelor stângi și minimul capetelor drepte determină intervalul comun.', 'n = int(input())\na = [tuple(map(int, input().split())) for _ in range(n)]\nl = max(x[0] for x in a)\nr = min(x[1] for x in a)\nprint(l, r) if l <= r else print("NU")', [('3\n1 8\n3 7\n2 5','3 5'),('2\n1 2\n3 4','NU'),('2\n1 2\n2 3','2 2')])
    add('liste', 'Paritate, vecini și felii', 'Citește două liste de întregi de aceeași lungime. În prima înlocuiește prin feliere elementele de pe poziții pare cu cele din a doua, apoi afișează prima listă. Pe linia a doua afișează elementele rămase care au aceeași paritate cu indicele lor de la 0.', 'a[::2]=b[::2] atribuie o felie cu pas; comprehensiunea poate folosi enumerate.', 'a = list(map(int, input().split()))\nb = list(map(int, input().split()))\na[::2] = b[::2]\nprint(*a)\nprint(*(x for i, x in enumerate(a) if x % 2 == i % 2))', [('1 2 3 4\n8 9 6 7','8 2 6 4\n8 6'),('1\n2','2\n2'),('\n\n','\n')])
    add('liste', 'Rotirea coloanelor și maximele', 'Citește n m și o matrice, apoi k ≥ 0. Rotește circular fiecare linie spre dreapta cu k, afișează matricea, apoi maximele liniilor pe ultima linie.', 'Redu k modulo m; rotirea liniilor realizează rotirea coloanelor.', 'n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\nk = int(input()) % m\nfor row in a:\n    print(*(row[-k:] + row[:-k] if k else row))\nprint(*(max(row) for row in a))', [('2 3\n1 2 3\n4 5 6\n1','3 1 2\n6 4 5\n3 6'),('1 1\n-2\n5','-2\n-2'),('1 2\n1 3\n0','1 3\n3')])
    add('colectii', 'Metode de mulțimi și dicționare', 'Prima linie conține valori distincte; a doua x. Creează set-ul, elimină x cu discard și afișează mulțimea crescător. Creează apoi d cu cheia x și valoarea 1, afișează d.pop(x,0) și d.get(x,0) pe a doua linie.', 'discard nu ridică eroare pentru un element absent; pop poate avea o valoare implicită.', 'a = set(map(int, input().split()))\nx = int(input())\na.discard(x)\nprint(*sorted(a))\nd = {x: 1}\nprint(d.pop(x, 0), d.get(x, 0))', [('1 2\n1','2\n1 0'),('1\n5','1\n1 0'),('\n2','\n1 0')])
    add('functii', 'Funcții ca argumente', 'Definește aplica(f,a), care aplică funcția f fiecărui element din a. Citește o listă de întregi și afișează pătratele folosind aplica cu lambda.', 'Funcția este un obiect care poate fi transmis altui apel; f(x) folosește comportamentul primit.', 'def aplica(f, a):\n    return [f(x) for x in a]\na = list(map(int, input().split()))\nprint(*aplica(lambda x: x * x, a))', [('2 -3','4 9'),('\n',''),('0','0')], requiredFunction='aplica')
    add('functii', 'Parametru keyword-only și valoare mutabilă', 'Definește adauga(x, lista=None, *, repeta=1). Returnează lista după adăugarea de repeta ori a lui x; fără listă dată creează una nouă. Citește x și r pe o linie. Afișează adauga(x,repeta=r), apoi adauga(9), ca valori pe două linii.', 'None evită partajarea unei liste implicite între apeluri; parametrul după * se transmite numai prin nume.', 'def adauga(x, lista=None, *, repeta=1):\n    if lista is None:\n        lista = []\n    lista.extend([x] * repeta)\n    return lista\nx, r = map(int, input().split())\nprint(*adauga(x, repeta=r))\nprint(*adauga(9))', [('2 3','2 2 2\n9'),('5 0','\n9'),('-1 1','-1\n9')], 'Aplicare', requiredFunction='adauga')
    add('fisiere', 'Citire sigură și excepții', 'date.in conține un întreg pe fiecare linie, unele linii putând fi invalide. Scrie suma numerelor valide și numărul liniilor invalide în date.out. O linie goală este invalidă.', 'Prinde ValueError numai în jurul conversiei fiecărei linii.', 's = bad = 0\nwith open("date.in") as f:\n    for line in f:\n        try:\n            s += int(line)\n        except ValueError:\n            bad += 1\nwith open("date.out", "w") as f:\n    print(s, bad, file=f)', [('3\nabc\n-1','2 1'),('','0 0'),('\n2','2 1')], 'Aplicare', inputFile='date.in', outputFile='date.out')
    add('complexitate', 'Numără operațiile într-o buclă imbricată', 'Citește 0 ≤ n ≤ 1000. O buclă i=0..n-1 are o buclă interioară j=i..n-1. Afișează numărul total de iterații interioare. Explică de ce este Θ(n²), iar memoria suplimentară este O(1).', 'Adună n+(n-1)+...+1; costul nu este estimat din timpul măsurat.', 'n = int(input())\nprint(n * (n + 1) // 2)', [('4','10'),('0','0'),('1','1')])
    add('divide', 'Perechile cu sumă dată', 'Citește o listă strict crescătoare și suma S. Afișează toate perechile distincte de valori cu suma S, o pereche pe linie, crescător după primul element. Fără perechi: NU. Folosește doi pointeri în O(n).', 'Suma prea mică mută stânga, suma prea mare mută dreapta; la egalitate mută ambele.', 'a = list(map(int, input().split()))\nS = int(input())\nl, r = 0, len(a) - 1\nfound = False\nwhile l < r:\n    s = a[l] + a[r]\n    if s == S:\n        print(a[l], a[r])\n        found = True\n        l += 1\n        r -= 1\n    elif s < S:\n        l += 1\n    else:\n        r -= 1\nif not found:\n    print("NU")', [('2 5 7 8 10 12 15 17 25\n20','5 15\n8 12'),('1 2\n5','NU'),('1\n2','NU')], 'Aplicare')
    chapters.append(dict(id='modular', title='15 · Module și testare', source='', supplemental=True, lesson=['Un modul propriu este un fișier .py cu funcții reutilizabile.', 'Separă funcțiile de calcul de citire și afișare. Testele mici verifică intrări și rezultate cunoscute.', 'assert verifică o condiție. Specificațiile, cazurile-limită și refactorizarea păstrează comportamentul observabil.'], example='def patrat(x):\n    return x * x\nassert patrat(-3) == 9', explain='Un assert fals oprește programul cu AssertionError; un test trecut confirmă numai acel caz.'))
    helper = 'def nr_cifre(n):\n    return 1 if n < 10 else 1 + nr_cifre(n // 10)\ndef invers(n):\n    def rec(n, r):\n        return r if n == 0 else rec(n // 10, r * 10 + n % 10)\n    return rec(n, 0)\ndef cmmdc(a, b):\n    return a if b == 0 else cmmdc(b, a % b)\n'
    add('modular', 'Construiește algoritmi_elementari.py', 'În câmpul algoritmi_elementari.py scrie funcțiile recursive nr_cifre(n), invers(n) și cmmdc(a,b), pentru naturale. În editorul principal importă-le. Datele de la tastatură sunt n a b. Afișează nr_cifre(n), invers(n), cmmdc(a,b). Și codul modulului tău este folosit la verificare.', 'nr_cifre(0)=1; invers(120)=21. La Euclid: cmmdc(a,b)=cmmdc(b,a%b), cu oprire b=0.', 'from algoritmi_elementari import nr_cifre, invers, cmmdc\nn, a, b = map(int, input().split())\nprint(nr_cifre(n), invers(n), cmmdc(a, b))', [(bundle(**{'algoritmi_elementari.py':helper,'_stdin':'120 18 24'}),'3 21 6'),(bundle(**{'algoritmi_elementari.py':helper,'_stdin':'0 0 7'}),'1 0 7'),(bundle(**{'algoritmi_elementari.py':helper,'_stdin':'9 0 0'}),'1 9 0')], 'Aplicare', inputFiles=['algoritmi_elementari.py'], editableFiles=['algoritmi_elementari.py'], fileStarters={'algoritmi_elementari.py':'def nr_cifre(n):\n    pass\n\ndef invers(n):\n    pass\n\ndef cmmdc(a, b):\n    pass\n'})
    add('modular', 'Teste înainte de implementare', 'Definește normalizare(s), care elimină spațiile de la margini, reduce grupurile de spații la unul și transformă literele în lowercase. Include assert-uri pentru text gol și spații multiple. Citește o linie și afișează normalizarea.', 'În TDD: scrii un caz care eșuează, implementezi, apoi refactorizezi cu toate testele verzi.', 'def normalizare(s):\n    return " ".join(s.lower().split())\nassert normalizare("") == ""\nassert normalizare(" A  B ") == "a b"\nprint(normalizare(input()))', [(' Ana  ARE ','ana are'),('\n',''),('x','x')], requiredFunction='normalizare')
    add('modular', 'Decorator de numărare', 'Definește numara(f), un decorator care mărește atributul wrapper.apeluri la fiecare apel și returnează rezultatul funcției. Decorează o funcție patrat; citește n, apeleaz-o pentru 0..n-1 și afișează suma rezultatelor și numărul apelurilor.', 'wrapper(*args,**kwargs) transmite argumentele către f. Contorul este atribut al funcției returnate.', 'def numara(f):\n    def wrapper(*args, **kwargs):\n        wrapper.apeluri += 1\n        return f(*args, **kwargs)\n    wrapper.apeluri = 0\n    return wrapper\n@numara\ndef patrat(x):\n    return x * x\nn = int(input())\nprint(sum(patrat(i) for i in range(n)), patrat.apeluri)', [('3','5 3'),('0','0 0'),('1','0 1')], 'Aprofundare', requiredFunction='numara')
    chapters.append(dict(id='obiecte', title='16 · Obiecte și organizarea proiectului', source='', supplemental=True, lesson=['O clasă definește obiecte cu date și comportament; __init__ stabilește starea inițială.', 'O clasă derivată poate reutiliza și suprascrie metode. Evită ca un atribut mutabil de clasă să fie confundat cu o listă proprie fiecărei instanțe.', 'Separă interfața, regulile de calcul și stocarea datelor; un repository ascunde operațiile de păstrare și căutare.'], example='class Contor:\n    def __init__(self):\n        self.valoare = 0\n    def creste(self):\n        self.valoare += 1', explain='Două obiecte Contor pot avea valori independente; self indică instanța curentă.'))
    add('obiecte', 'Clasă pentru un cont', 'Definește Cont cu sold inițial și metode depune(s) și retrage(s). Retragerea reușește numai dacă s ≤ sold și returnează True/False. Citește sold, suma depusă și suma retrasă pe o linie; afișează rezultatul retragerii și soldul final.', 'Metodele modifică self.sold; return și afișarea sunt operații distincte.', 'class Cont:\n    def __init__(self, sold):\n        self.sold = sold\n    def depune(self, s):\n        self.sold += s\n    def retrage(self, s):\n        if s > self.sold:\n            return False\n        self.sold -= s\n        return True\na, b, c = map(int, input().split())\ncont = Cont(a)\ncont.depune(b)\nprint(cont.retrage(c), cont.sold)', [('10 5 12','True 3'),('0 2 3','False 2'),('1 0 1','True 0')], 'Aplicare')
    add('obiecte', 'Moștenire și suprascriere', 'Definește clasa Produs cu preț și metoda cost(), apoi ProdusRedus care suprascrie cost pentru reducere procentuală. Citește prețul și reducerea 0..100; afișează costul produsului de bază și al celui redus cu două zecimale.', 'super().__init__ reutilizează inițializarea; metoda suprascrisă folosește aceeași interfață.', 'class Produs:\n    def __init__(self, pret):\n        self.pret = pret\n    def cost(self):\n        return self.pret\nclass ProdusRedus(Produs):\n    def __init__(self, pret, reducere):\n        super().__init__(pret)\n        self.reducere = reducere\n    def cost(self):\n        return self.pret * (1 - self.reducere / 100)\np, r = map(float, input().split())\nprint(f"{Produs(p).cost():.2f}", f"{ProdusRedus(p, r).cost():.2f}")', [('100 25','100.00 75.00'),('5 0','5.00 5.00'),('10 100','10.00 0.00')], 'Aplicare')
    add('obiecte', 'Repository în memorie', 'Citește n și n perechi cod valoare. Creează clasa Repository cu adauga(cod,valoare), sterge(cod), cauta(cod). Citește codul de șters, apoi cel căutat. Afișează valoarea sau NU. Adăugarea pe același cod înlocuiește valoarea.', 'Dicționarul este ascuns în obiect; operațiile de stocare sunt grupate separat de citire/afișare.', 'class Repository:\n    def __init__(self):\n        self.date = {}\n    def adauga(self, cod, valoare):\n        self.date[cod] = valoare\n    def sterge(self, cod):\n        self.date.pop(cod, None)\n    def cauta(self, cod):\n        return self.date.get(cod, "NU")\nr = Repository()\nn = int(input())\nfor _ in range(n):\n    c, v = input().split()\n    r.adauga(c, v)\nr.sterge(input())\nprint(r.cauta(input()))', [('2\na 1\nb 2\na\nb','2'),('1\na 5\na\na','NU'),('0\nx\ny','NU')], 'Aprofundare')
